func (f *Forwarder) getCachedCertificate(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	creds, ok := f.credentialCache.Get(ctx.key())
	if !ok {
		return nil
	}
	config := creds.(*tls.Config)
	if len(config.Certificates) == 0 || config.Certificates[0].Leaf == nil ||
		config.Certificates[0].Leaf.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.credentialCache.Remove(ctx.key())
		return nil
	}
	return config
}

func (f *Forwarder) getOrRequestCertificate(ctx authContext) (*tls.Config, error) {
	for {
		if config := f.getCachedCertificate(ctx); config != nil {
			return config, nil
		}
		wait, done := f.getOrCreateRequestContext(ctx.key())
		if done == nil {
			select {
			case <-wait.Done():
				continue
			case <-f.ctx.Done():
				return nil, trace.BadParameter("forwarder is closing, aborting the request")
			}
		}
		// Recheck after taking ownership: the previous requester may have
		// completed between the first cache lookup and this lock.
		if config := f.getCachedCertificate(ctx); config != nil {
			done()
			return config, nil
		}
		config, err := f.requestCertificate(ctx)
		if err == nil && len(config.Certificates) > 0 && config.Certificates[0].Leaf != nil {
			expires := config.Certificates[0].Leaf.NotAfter
			if !expires.Before(f.Clock.Now().Add(time.Minute)) {
				ttl := expires.Sub(f.Clock.Now().Add(time.Minute))
				if ctx.sessionTTL > 0 && ctx.sessionTTL < ttl {
					ttl = ctx.sessionTTL
				}
				err = f.credentialCache.Set(ctx.key(), config, ttl)
			}
		}
		done()
		return config, trace.Wrap(err)
	}
}

